package edu.klh.soa.workflow;import org.springframework.context.annotation.*;import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;import org.springframework.kafka.core.ConsumerFactory;import org.springframework.kafka.listener.DefaultErrorHandler;import org.springframework.util.backoff.FixedBackOff;import org.apache.kafka.common.TopicPartition;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;@Configuration public class KafkaConfig {@Bean public ConcurrentKafkaListenerContainerFactory<String,java.util.Map<String,Object>> kafkaListenerContainerFactory(ConsumerFactory<String,java.util.Map<String,Object>> cf,KafkaTemplate<Object,Object> template){var f=new ConcurrentKafkaListenerContainerFactory<String,java.util.Map<String,Object>>();f.setConsumerFactory(cf);f.setCommonErrorHandler(new DefaultErrorHandler(new DeadLetterPublishingRecoverer(template,(r,e)->new TopicPartition("soa.s02.t17.events.DLT",r.partition())),new FixedBackOff(1000L,2)));return f;}}
